// Shared two-decimal rounding, used everywhere money is rounded.
export function round(value) {
	return Math.round((value + Number.EPSILON) * 100) / 100;
}

// Shared discount-rate ladder: volume tiers plus loyalty tiers, capped at 0.2.
export function discountRateFor(subtotal, order) {
	let volumeRate = 0;
	if (subtotal >= 1000) {
		volumeRate = 0.15;
	} else if (subtotal >= 500) {
		volumeRate = 0.1;
	} else if (subtotal >= 200) {
		volumeRate = 0.05;
	}
	let loyaltyRate = 0;
	if (order.loyaltyTier === "gold") {
		loyaltyRate = 0.05;
	} else if (order.loyaltyTier === "silver") {
		loyaltyRate = 0.02;
	}
	let discountRate = Math.round((volumeRate + loyaltyRate) * 10000) / 10000;
	if (discountRate > 0.2) {
		discountRate = 0.2;
	}
	return discountRate;
}

import { round } from "./rounding.mjs";

// Shared region tax lookup; returns the rounded tax amount on the given taxable total.
export function taxFor(taxable, region) {
	let taxRate = 0;
	if (region === "eu") {
		taxRate = 0.21;
	} else if (region === "us") {
		taxRate = 0.07;
	}
	return round(taxable * taxRate);
}

import { round } from "./rounding.mjs";
import { discountRateFor } from "./discount.mjs";
import { taxFor } from "./tax.mjs";

// Order pricing. Grown one requirement at a time; nobody has been back since.

function sumLines(lines) {
	let subtotal = 0;
	for (const line of lines) {
		const quantity = Number(line.quantity ?? 0);
		const unitPrice = Number(line.unitPrice ?? 0);
		if (!Number.isFinite(quantity) || !Number.isFinite(unitPrice)) {
			throw new TypeError(`line ${line.sku ?? "?"} has a non-numeric quantity or unitPrice`);
		}
		if (quantity < 0 || unitPrice < 0) {
			throw new RangeError(`line ${line.sku ?? "?"} has a negative quantity or unitPrice`);
		}
		subtotal += quantity * unitPrice;
	}
	return round(subtotal);
}

function computeShipping(taxable, shippingSpeed) {
	let shipping = 0;
	if (taxable < 300) {
		shipping = 12.5;
	}
	if (shippingSpeed === "express") {
		shipping = round(shipping + 20);
	}
	return shipping;
}

export function applyOrderPricing(order) {
	const subtotal = sumLines(order.lines ?? []);
	const discountRate = discountRateFor(subtotal, order);
	const discount = round(subtotal * discountRate);
	const taxable = round(subtotal - discount);
	const tax = taxFor(taxable, order.region);
	const shipping = computeShipping(taxable, order.shippingSpeed);
	const total = round(taxable + tax + shipping);
	return { subtotal, discountRate, discount, taxable, tax, shipping, total };
}

import { round } from "./rounding.mjs";
import { discountRateFor } from "./discount.mjs";
import { taxFor } from "./tax.mjs";

// Invoice rendering. The totals block was copied out of pricing.mjs when invoicing was added,
// and the two have been edited in parallel ever since.

export function renderInvoiceTotals(order) {
	const lines = order.lines ?? [];
	let subtotal = 0;
	for (const line of lines) {
		subtotal += Number(line.quantity ?? 0) * Number(line.unitPrice ?? 0);
	}
	subtotal = round(subtotal);
	const discountRate = discountRateFor(subtotal, order);
	const discount = round(subtotal * discountRate);
	const taxable = round(subtotal - discount);
	const tax = taxFor(taxable, order.region);
	const rendered = [
		`Subtotal: ${subtotal.toFixed(2)}`,
		`Discount (${(discountRate * 100).toFixed(0)}%): -${discount.toFixed(2)}`,
		`Tax: ${tax.toFixed(2)}`,
	];
	return { lines: rendered, discountRate, tax };
}
